class HallucinationDetector(Estimator):
    def __init__(self, context: Dict[str, Any]) -> None:
        super().__init__(
            context,
            stats_dependencies=[
                "sequence_logprobs",
            ],
            level="sequence",
        )

    def __call__(self, stats: Dict[str, np.ndarray]) -> np.ndarray:
        # Input: List[np.ndarray] of shape (n_i - 1,)
        # Output: np.ndarray of shape [N]

        # Hypothesis: Hallucinations exhibit higher local variance in log-probability 
        # (confidence instability) compared to coherent text.

        scores = []
        for seq_logprobs in stats["sequence_logprobs"]:
            n = len(seq_logprobs)
            if n < 2:
                scores.append(0.0)
                continue

            # Compute variance of the sequence log-probabilities
            # This measures local volatility of the model's confidence
            seq_variance = np.var(seq_logprobs)
            scores.append(seq_variance)

        return np.array(scores, dtype=np.float32)
# Score achieved with the function above: 58.0598


class HallucinationDetector(Estimator):
    def __init__(self, context: Dict[str, Any]) -> None:
        super().__init__(
            context,
            stats_dependencies=[
                "sequence_logprobs",
            ],
            level="sequence",
        )

    def __call__(self, stats: Dict[str, np.ndarray]) -> np.ndarray:
        """
        Calculates the average negative log-probability per token.

        Aggregation Principle: Average the NLL across the sequence length.
        This mitigates the sequence-length bias present in the total NLL detector
        while capturing the general uncertainty of the generated text.

        Hypothesis for future: This detector assumes that hallucinations are
        characterized by low average confidence (high NLL) across the sequence
        rather than just high total uncertainty.
        """
        scores = []
        for seq_logprobs in stats["sequence_logprobs"]:
            # Avoid division by zero for empty sequences
            length = len(seq_logprobs)
            if length > 0:
                avg_neg_logprob = -np.mean(seq_logprobs)
            else:
                avg_neg_logprob = 0.0
            scores.append(avg_neg_logprob)
        return np.array(scores, dtype=np.float32)
# Score achieved with the function above: 71.9969
